use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\DB;
Schema::create('records', function ($t) {
    $t->id();
    $t->text('notes')->nullable();
});
DB::table('records')->insert(['notes' => 'original text']);
Schema::table('records', function ($t) {
    $t->dropColumn('notes');
});
Schema::table('records', function ($t) {
    $t->text('notes')->nullable();
});
echo DB::table('records')->value('notes') === null ? 'null' : 'restored';
